  v_points jsonb;
  v_route record;
  v_count integer;
  v_km double precision;
  v_max_gap double precision;
  v_center_gap double precision;
  v_end_gap double precision;
  v_invalid integer;
begin
  select r.id,r.latitude,r.longitude,r.distance_km,t.status
  into v_route from public.hiking_routes r
    join public.hiking_route_tracks t on t.route_id=r.id
  where r.id='osm-relation-21241677'
    and r.source='openstreetmap'
    and r.name='Miedes de Aragón - Cerro Magdalena'
    and r.route_ref='SL-Z 45'
    and r.official_url='https://www.senderosfam.es/ruta/ficha/932/'
